// MachineSettlementChannel defines model for MachineSettlementChannel.
type MachineSettlementChannel struct {
	// ChannelId The escrow channel id: keccak256(chainId, escrow, customer, host, feeReceiver, feeBps, salt)
	ChannelId string `json:"channelId"`

	// ChargedAmount What the channel was charged so far, micro-USD
	ChargedAmount string `json:"chargedAmount"`

	// ClaimedAmount The channel's claimed total, as indexed
	ClaimedAmount string `json:"claimedAmount"`

	// CoveredAt Until when a signed voucher covered everything the channel was charged; once it falls more than voucherGraceIntervals behind, the sandboxes are unpaid
	CoveredAt time.Time `json:"coveredAt"`

	// CustomerAddress EIP-55 checksummed address
	CustomerAddress string `json:"customerAddress"`

	// CustomerPendingAmount What the customer requested to withdraw; claims still draw on it until it unlocks
	CustomerPendingAmount string `json:"customerPendingAmount"`

	// CustomerWithdrawalUnlockAt When the customer's pending withdrawal unlocks, on the escrow's unfrozen clock; Snapflow claims the channel before then
	CustomerWithdrawalUnlockAt *time.Time `json:"customerWithdrawalUnlockAt"`
	FeeBps                     int        `json:"feeBps"`

	// FeeReceiverAddress EIP-55 checksummed address
	FeeReceiverAddress string `json:"feeReceiverAddress"`

	// HostAddress The machine's host key the channel pays
	HostAddress      string             `json:"hostAddress"`
	PaymentChannelId openapi_types.UUID `json:"paymentChannelId"`
	Salt             string             `json:"salt"`

	// Sandboxes The sandboxes the channel pays for whose charges are still being metered
	Sandboxes   []MachineChannelSandbox `json:"sandboxes"`
	Signer      *MachineVoucherSigner   `json:"signer"`
	SigningMode VoucherSigningMode      `json:"signingMode"`

	// Voucher Latest signed voucher, none before the first one is signed
	Voucher *MachineSignedVoucher `json:"voucher"`

	// VoucherLimit What held the latest voucher below the charges: the customer's balance or signer ran short
	VoucherLimit *VoucherLimit `json:"voucherLimit"`
}

// MachineSettlementDocument defines model for MachineSettlementDocument.
type MachineSettlementDocument struct {
	Channels []MachineSettlementChannel `json:"channels"`

	// CreditedAmount The host key's escrow balance from earlier claims, as indexed: a settlement withdraws it together with what it claims, micro-USD
	CreditedAmount string       `json:"creditedAmount"`
	Digest         string       `json:"digest"`
	Domain         EscrowDomain `json:"domain"`

	// HostAddress The machine's current host key, null before it enrolled one
	HostAddress *string `json:"hostAddress"`

	// LatestSettlement The host key's latest settlement
	LatestSettlement *HostSettlement `json:"latestSettlement"`

	// PayoutAddress The organization's payout wallet: the payout a HostWithdrawal must name
	PayoutAddress *string `json:"payoutAddress"`

	// PayoutMinimumMicroUsd What a payout must bring the host after its relay fee, micro-USD, before the agent settles; smaller earnings carry over, and Snapflow claims any that near a deadline into the credited balance at its own gas
	PayoutMinimumMicroUsd string                   `json:"payoutMinimumMicroUsd"`
	Relayer               MachineSettlementRelayer `json:"relayer"`

	// SchemaVersion Version of this document shape
	SchemaVersion          int           `json:"schemaVersion"`
	VoucherGraceIntervals  int           `json:"voucherGraceIntervals"`
	VoucherIntervalSeconds int           `json:"voucherIntervalSeconds"`
	Windows                EscrowWindows `json:"windows"`
}

// MachineSettlementRelayer defines model for MachineSettlementRelayer.
type MachineSettlementRelayer struct {
	// Address Snapflow's relayer: the relayer a HostWithdrawal sent through the settle endpoint names
	Address string `json:"address"`

	// MaxBatchSize Most claims one settlement may carry (MAX_BATCH_SIZE)
	MaxBatchSize int `json:"maxBatchSize"`

	// Quote The current relay fee quote, priced from the chain's live gas plus the relay fee margin: base + perClaim * claims, at most maximum; null while the chain is unreachable
	Quote *MachineRelayFeeQuote `json:"quote"`

	// SignatureLifetimeSeconds Seconds ahead of now the HostWithdrawal deadline should lie
	SignatureLifetimeSeconds int `json:"signatureLifetimeSeconds"`
}

// MachineSignedVoucher defines model for MachineSignedVoucher.
type MachineSignedVoucher struct {
	// CumulativeAmount Total the host may claim over the channel, fee included, in USDC base units (micro-USD)
	CumulativeAmount string `json:"cumulativeAmount"`

	// Customer Paying funding wallet
	Customer string `json:"customer"`

	// Digest EIP-712 digest
	Digest string `json:"digest"`

	// FeeBps Fee share of every claim, in basis points
	FeeBps int `json:"feeBps"`

	// FeeReceiver EIP-55 checksummed address
	FeeReceiver string `json:"feeReceiver"`

	// Host Paid host: a machine's host key, or Snapflow's platform receiver
	Host string `json:"host"`

	// Metadata Commitment to the usage receipt chains of the sandboxes the channel paid for when the voucher was issued
	Metadata string `json:"metadata"`

	// Salt The channel salt
	Salt      string `json:"salt"`
	Sequence  int    `json:"sequence"`
	Signature string `json:"signature"`

	// Signer The key that signed; claims name it as the signer
	Signer string `json:"signer"`

	// Timestamp Unix seconds
	Timestamp string `json:"timestamp"`
}

